/// Reproduces `DateTime::__elephc_display_timezone($name)`.
///
/// libc's POSIX `TZ` inverts a numeric offset's sign and needs a zone name.
/// Numeric offsets and known abbreviations are converted to an `Etc/GMT∓H` or
/// `XXX∓HH:MM` zone; the public `timezone_name` keeps PHP's original spelling.
pub(super) fn display_timezone() -> Vec<Stmt> {
    vec![
        // A tz-database identifier must keep its DST rules, but libc needs the
        // canonical spelling and an alias link that its zoneinfo ships. Resolve it
        // through the case-insensitive ALL_WITH_BC table first.
        s_if(
            e_not(e_var("fixed")),
            vec![
                s_assign(
                    "canonical",
                    e_self_call("__elephc_tz_identifier", vec![e_var("name")]),
                ),
                s_if(
                    e_binop(e_var("canonical"), BinOp::StrictNotEq, e_bool(false)),
                    vec![s_return(e_var("canonical"))],
                    Vec::new(),
                    Some(vec![s_return(e_var("name"))]),
                ),
            ],
            Vec::new(),
            None,
        ),
        // UTC/GMT are already valid libc zone names; remapping them would change
        // `format('e')` from the PHP-visible name to `Etc/GMT+0`.
        s_if(
            e_binop(
                e_binop(e_var("name"), BinOp::StrictEq, e_str("UTC")),
                BinOp::Or,
                e_binop(e_var("name"), BinOp::StrictEq, e_str("GMT")),
            ),
            vec![s_return(e_var("name"))],
            Vec::new(),
            None,
        ),
        s_if(
            e_binop(
                e_binop(e_call("strlen", vec![e_var("name")]), BinOp::StrictEq, e_int(6)),
                BinOp::And,
                e_binop(
                    e_binop(e_index(e_var("name"), e_int(0)), BinOp::StrictEq, e_str("+")),
                    BinOp::Or,
                    e_binop(e_index(e_var("name"), e_int(0)), BinOp::StrictEq, e_str("-")),
                ),
            ),
            vec![s_if(
                e_binop(e_index(e_var("name"), e_int(3)), BinOp::StrictEq, e_str(":")),
                vec![
                    s_assign(
                        "offset",
                        e_binop(
                            e_binop(
                                e_binop(
                                    e_cast(CastType::Int, e_call("substr", vec![e_var("name"), e_int(1), e_int(2)])),
                                    BinOp::Mul,
                                    e_int(3_600),
                                ),
                                BinOp::Add,
                                e_binop(
                                    e_cast(CastType::Int, e_call("substr", vec![e_var("name"), e_int(4), e_int(2)])),
                                    BinOp::Mul,
                                    e_int(60),
                                ),
                            ),
                            BinOp::Mul,
                            e_ternary(
                                e_binop(
                                    e_index(e_var("name"), e_int(0)),
                                    BinOp::StrictEq,
                                    e_str("+"),
                                ),
                                e_int(1),
                                e_int(-1),
                            ),
                        ),
                    ),
                    s_return(e_self_call(
                        "__elephc_offset_zone",
                        vec![e_var("offset")],
                    )),
                ],
                Vec::new(),
                None,
            )],
            Vec::new(),
            None,
        ),
        s_assign(
            "offset",
            e_self_call("__elephc_abbr_offset", vec![e_var("name")]),
        ),
        s_if(
            e_binop(
                e_var("offset"),
                BinOp::StrictNotEq,
                e_int(-2_147_483_648),
            ),
            vec![s_return(e_self_call(
                "__elephc_offset_zone",
                vec![e_var("offset")],
            ))],
            Vec::new(),
            None,
        ),
        s_return(e_var("name")),
    ]
}

/// Emits the `timezone_type` 2 (abbreviation) restoration sequence.
///
/// PHP treats the abbreviation as a fixed offset: the wall clock is parsed in UTC
/// and the abbreviation offset is subtracted. The public zone name keeps the
/// abbreviation so `getTimezone()->getName()` reports it.
pub(super) fn restore_abbreviation(datetime_var: &str, zone_var: &str) -> Vec<Stmt> {
    vec![
        s_assign("zone", e_call("strtoupper", vec![e_var(zone_var)])),
        s_assign(
            "offset",
            e_self_call("__elephc_abbr_offset", vec![e_var(zone_var)]),
        ),
        s_if(
            e_binop(e_var("offset"), BinOp::StrictEq, e_int(-2_147_483_648)),
            vec![s_throw(e_new(
                "DateMalformedStringException",
                vec![e_binop(
                    e_binop(
                        e_str("Unknown timezone abbreviation ("),
                        BinOp::Concat,
                        e_var(zone_var),
                    ),
                    BinOp::Concat,
                    e_str(")"),
                )],
            ))],
            Vec::new(),
            None,
        ),
        s_assign(
            "__ts",
            e_call(
                "strtotime",
                vec![e_binop(
                    e_var(datetime_var),
                    BinOp::Concat,
                    e_str(" UTC"),
                )],
            ),
        ),
        s_if(
            e_binop(e_var("__ts"), BinOp::StrictEq, e_bool(false)),
            vec![s_throw(e_new(
                "DateMalformedStringException",
                vec![e_binop(
                    e_binop(
                        e_str("Failed to parse time string ("),
                        BinOp::Concat,
                        e_var(datetime_var),
                    ),
                    BinOp::Concat,
                    e_str(")"),
                )],
            ))],
            Vec::new(),
            None,
        ),
        s_prop_assign(
            e_this(),
            "timestamp",
            e_binop(e_var("__ts"), BinOp::Sub, e_var("offset")),
        ),
        // PHP stores the abbreviation upper-cased: a serialized `timezone="cest"`
        // reports `CEST` from format('e'), format('T') and getTimezone()->getName().
        s_prop_assign(e_this(), "timezone_name", e_var("zone")),
        s_prop_assign(e_this(), "__elephc_fixed_zone", e_bool(true)),
    ]
}

